-- Vector Golf Performance · 120 player-ready putting drills
on conflict(code) do update set title=excluded.title,category=excluded.category,stage=excluded.stage,purpose=excluded.purpose,setup=excluded.setup,instructions=excluded.instructions,intention=excluded.intention,equipment=excluded.equipment,dosage=excluded.dosage,pass_criterion=excluded.pass_criterion,progression=excluded.progression,regression=excluded.regression,source_reference=excluded.source_reference,status=excluded.status,updated_at=now()
where (library_items.title,library_items.category,library_items.stage,library_items.purpose,library_items.setup,library_items.instructions,library_items.intention,library_items.equipment,library_items.dosage,library_items.pass_criterion,library_items.progression,library_items.regression,library_items.source_reference,library_items.status) is distinct from (excluded.title,excluded.category,excluded.stage,excluded.purpose,excluded.setup,excluded.instructions,excluded.intention,excluded.equipment,excluded.dosage,excluded.pass_criterion,excluded.progression,excluded.regression,excluded.source_reference,excluded.status);

do $$ declare total integer;ready integer;sc integer;fa integer;sq integer;cp integer;begin select count(*),count(*) filter(where instruction_complete),count(*) filter(where code like 'PUT-SC-%'),count(*) filter(where code like 'PUT-FA-%'),count(*) filter(where code like 'PUT-SQ-%'),count(*) filter(where code like 'PUT-CP-%') into total,ready,sc,fa,sq,cp from public.library_items where code like 'PUT-%';if total<>120 or ready<>120 or sc<>30 or fa<>30 or sq<>30 or cp<>30 then raise exception 'Putting library validation failed: total %, ready %, SC %, FA %, SQ %, CP %',total,ready,sc,fa,sq,cp;end if;end $$;

