insert into public.library_items(code,item_type,title,category,stage,purpose,setup,instructions,intention,equipment,dosage,pass_criterion,progression,regression,source_reference,status)
values
('PUT-SC-01','golf_drill','Three-Foot Ladder','Putting · Speed Control','Learn','Three-Foot Ladder develops start speed and distance control through a specific, measurable putting task.','Mark the stated finishing target or zone with tees. Begin from a measured putting distance with three balls. For Three-Foot Ladder, use station variation 1: flat line.','1. Read the putt and predict the finishing speed. 2. Roll each ball using the same routine. 3. Leave every ball where it stops and score its finishing depth. 4. Change distance or slope as directed by the drill title and repeat.','Control the energy of the stroke so the ball finishes at the intended depth rather than merely travelling on line.','Putter, balls, tees and measuring reference','Complete 3 sets of 5 putts.','At least 12 of 15 balls finish in the defined capture zone.','Narrow the capture zone, randomise distance or add slope.','Widen the capture zone and use one fixed distance.','Vector Putting Drill Library · 120 Drill Collection','approved'),
